      "ui.sync.modal.title": "\u9009\u62E9\u540C\u6B65\u6A21\u5F0F",
      "ui.sync.modal.labelNewToLearnKit": "\u8BBE\u7F6E\u540C\u6B65\u6A21\u5F0F",
      "ui.sync.modal.bodyIntro": "\u540C\u6B65\u6A21\u5F0F\u51B3\u5B9A LearnKit \u4F1A\u5C06\u54EA\u4E9B\u5185\u5BB9\u8BC6\u522B\u4E3A\u95EA\u5361\uFF0C\u4EE5\u53CA\u5B83\u53EF\u4EE5\u5BF9 Markdown \u505A\u54EA\u4E9B\u8C03\u6574\u3002\u5BF9\u4E8E\u5927\u591A\u6570\u4E0D\u6253\u7B97\u4F7F\u7528\u7B80\u5199\u95EA\u5361\u7684\u65B0\u7528\u6237\uFF0C\u6211\u4EEC\u5EFA\u8BAE\u4F7F\u7528 Simple \u6A21\u5F0F\u3002\u4F60\u4E4B\u540E\u53EF\u968F\u65F6\u5728\u8BBE\u7F6E\u4E2D\u66F4\u6539\u3002\u4F60\u7684\u77E5\u8BC6\u5E93\u76EE\u524D\u6709 {totalWithCards} \u4E2A\u5305\u542B\u95EA\u5361\u7684\u7B14\u8BB0\u3002",
      "ui.sync.modal.labelFull": "Full\uFF08\u89C4\u8303\u5316\uFF09",
      "ui.sync.modal.bodyFull": "\u626B\u63CF LearnKit \u89C4\u8303\u8BED\u6CD5\u4E0E\u7B80\u5199\u4EE3\u7801\uFF0C\u5E76\u5C06\u7B80\u5199\u8F6C\u6362\u4E3A LearnKit \u89C4\u8303\u683C\u5F0F\u3002\u8FD9\u6709\u52A9\u4E8E\u8FC1\u79FB\u4F7F\u7528 :: \u4F5C\u4E3A\u95EE\u7B54\u5206\u9694\u7B26\u7684\u63D2\u4EF6\u5361\u7247\u3002\u8F6C\u6362\u540E\uFF0C\u8FD9\u4E9B\u5361\u7247\u5C06\u4E0D\u518D\u4E0E\u4F9D\u8D56\u7B80\u5199\u7ED3\u6784\u7684\u63D2\u4EF6\u5411\u540E\u517C\u5BB9\uFF0C\u4F46\u53EF\u83B7\u5F97\u5B8C\u6574\u7684 LearnKit \u529F\u80FD\u3002\u5C11\u6570\u60C5\u51B5\u4E0B\uFF0C\u975E\u95EA\u5361\u63D2\u4EF6\u5728 Markdown \u4E2D\u4F7F\u7528\u7684 :: \u4E5F\u53EF\u80FD\u88AB\u8BEF\u5339\u914D\u5E76\u8F6C\u6362\u3002\u82E5\u4F60\u4E0D\u9700\u8981\u8FC1\u79FB\uFF0C\u5EFA\u8BAE\u4F7F\u7528 Simple \u6A21\u5F0F\u3002",
      "ui.sync.modal.labelSimple": "\u5141\u8BB8\u7B80\u5355\u540C\u6B65",
      "ui.sync.modal.bodySimple": "\u7B80\u5355\u540C\u6B65\u4EC5\u4F1A\u4E3A\u95EA\u5361\u6DFB\u52A0\u7F3A\u5931\u7684\u951A\u70B9 ID \u4EE5\u8FFD\u8E2A\u5B83\u4EEC\uFF0C\u4E0D\u4F1A\u5BF9\u7B14\u8BB0\u8FDB\u884C\u4EFB\u4F55\u5176\u4ED6\u66F4\u6539\u3002\u8FD9\u4E9B\u662F\u6BCF\u5F20\u95EA\u5361\u4E0A\u65B9\u7684\u5C0F\u578B\u4E0D\u53EF\u89C1\u6CE8\u91CA\uFF0C\u683C\u5F0F\u4E3A ^learnkit-123456789\u3002",
      "ui.sync.modal.labelSimpleSafe": "\u7B80\u5355",
      "ui.sync.modal.bodySimpleSafe": "\u4EC5\u626B\u63CF LearnKit \u89C4\u8303\u8BED\u6CD5\u3002\u4E0D\u4F1A\u89E3\u6790\u65B0\u7684 :: \u7B80\u5199\u4EE3\u7801\uFF0C\u53EF\u964D\u4F4E\u4E0E\u5176\u4ED6\u63D2\u4EF6\u51B2\u7A81\u7684\u98CE\u9669\u3002\u8FD9\u662F\u6700\u5B89\u5168\u7684\u540C\u6B65\u9009\u9879\u3002",
      "ui.sync.modal.bodySimpleSafeRecommendation": "\u5982\u679C\u4F60\u4E0D\u6253\u7B97\u4F7F\u7528\u7B80\u5199\u4EE3\u7801\uFF0C\u6216\u4E0D\u9700\u8981\u4ECE\u5176\u4ED6\u95EA\u5361\u63D2\u4EF6\u8FC1\u79FB\u9898\u76EE\uFF0C\u6211\u4EEC\u5F3A\u70C8\u5EFA\u8BAE\u4F7F\u7528\u6B64\u6A21\u5F0F\u3002",
      "ui.sync.modal.labelSimpleCompat": "Full\uFF08\u4FDD\u7559\u683C\u5F0F\uFF09",
      "ui.sync.modal.bodySimpleCompat": "\u626B\u63CF LearnKit \u89C4\u8303\u8BED\u6CD5\u4E0E\u7B80\u5199\u4EE3\u7801\uFF0C\u4FDD\u7559\u7B80\u5199\u7ED3\u6784\uFF0C\u5E76\u5728\u9700\u8981\u65F6\u8865\u5145 LearnKit \u951A\u70B9\u3002\u5728\u7EE7\u7EED\u4F7F\u7528 LearnKit \u540C\u6B65\u7684\u540C\u65F6\uFF0C\u5B83\u4E0E\u5176\u4ED6\u95EA\u5361\u63D2\u4EF6\u901A\u5E38\u66F4\u517C\u5BB9\u3002\u5C11\u6570\u60C5\u51B5\u4E0B\uFF0C\u975E\u95EA\u5361\u63D2\u4EF6\u5728 Markdown \u4E2D\u4F7F\u7528\u7684 :: \u4ECD\u53EF\u80FD\u88AB\u5339\u914D\u5E76\u52A0\u951A\u3002\u82E5\u4F60\u4E0D\u9700\u8981\u7B80\u5199\u517C\u5BB9\u6027\uFF0C\u5EFA\u8BAE\u4F7F\u7528 Simple \u6A21\u5F0F\u3002",
