  // ── Vault-wide card deletion ──────────────
  /**
   * Walks every markdown file in the vault and removes:
   *  - Sprout anchor lines (`^sprout-NNNNNNNNN`)
   *  - Card blocks (Q/MCQ/CQ start lines + following field lines)
   *
   * Returns counts of files modified and lines/anchors/cards removed.
   */
  async deleteAllSproutDataFromVault() {
    const mdFiles = this.app.vault.getMarkdownFiles();
    let filesTouched = 0;
    let anchorsRemoved = 0;
    let cardsRemoved = 0;
    let linesRemoved = 0;
    for (const f of mdFiles) {
      const text2 = await this.app.vault.read(f);
      const lines = text2.split(/\r?\n/);
      const out = [];
      let changed = false;
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const t2 = line.trim();
        if (isAnchorLine(t2)) {
          anchorsRemoved++;
          linesRemoved++;
          changed = true;
          continue;
        }
        if (isCardStartLine(t2) && looksLikeCardBlock(lines, i)) {
          cardsRemoved++;
          linesRemoved++;
          changed = true;
          let j2 = i + 1;
          for (; j2 < lines.length; j2++) {
            const tj = lines[j2].trim();
            if (isCardStartLine(tj) && looksLikeCardBlock(lines, j2)) break;
            if (!tj || isAnchorLine(tj) || isFieldLine(tj)) {
              if (isAnchorLine(tj)) anchorsRemoved++;
              linesRemoved++;
              continue;
            }
            break;
          }
          i = j2 - 1;
          continue;
        }
        out.push(line);
      }
      if (changed) {
        filesTouched++;
        await this.app.vault.modify(f, out.join("\n"));
      }
    }
    return { filesTouched, anchorsRemoved, cardsRemoved, linesRemoved };
  }
